 let source=sources[0],generation=0,items=[],catalog=[],total=0,next=0,busy=false,wayback=null,reference=null,showingA=false,selected=null,timer=null,disposed=false,lastView='',waybackCatalog=null,aiRevision=0,aiSnapshot=null;
