 for(const [label,q] of [['🌱 Vegetación','Analizar vegetación'],['🔥 Zonas quemadas','Analizar zonas quemadas'],['💧 Agua o humedad','Analizar agua o humedad'],['🏙️ Crecimiento urbano','Analizar crecimiento urbano'],['🕒 Comparar fechas','Comparar dos fechas'],['🛰️ Mejor imagen','Mejor imagen'],['✨ ¿Qué puedo analizar aquí?','Qué puedo analizar aquí']])button(label,aiChips,()=>app.actions.invoke('geoai-ask',{question:q}));aiInput.onkeydown=e=>{if(e.key==='Enter')aiSend.click();};
